  and m.module_number = 4 and l.lesson_number = 7;

update public.lessons l set enhancements = $ench${"industryStory":"The most common bias in QA hiring is not dramatic prejudice — it is a team quietly cloning itself and calling it a high bar. Panel after panel favours the candidate who reasons and talks like the people already in the room, and every rejection is sincerely framed as \"not quite at our level\" or \"not a fit.\" Then the team wonders why it keeps being strong at the same things and blind in the same places. Take a team that starts scoring \"what does this person add that we lack\" as an explicit criterion: its hires change within two rounds — and so, a year later, does the range of problems the team can actually catch.","visualAid":{"type":"comparison","title":"Common hiring biases and the mechanism that counters each","headers":["Bias","How it shows up","Counter-mechanism"],"rows":[["Affinity / similarity","\"Great culture fit\" = just like us","Score \"culture add\"; diverse panel"],["Halo / horns","One strong trait forgives all weaknesses","Score each capability independently before an overall view"],["Confirmation","Decide early, then gather supporting evidence","Fixed questions; disconfirm-your-favourite habit"],["Prestige","Known employer/university stands in for evidence","Blind-ish first-pass screening"],["Fluency / articulacy","Confident talker read as capable tester","Assess reasoning via practical, not just conversation"]]},"davidTip":"Almost every interviewer, yourself included, believes they are the fair one. That belief is the bias. The people who actually hire fairly are not the ones with the best intentions — they are the ones who put mechanisms between their gut and their decision: a scorecard, independent scores before the debrief, a diverse panel, a deliberate hunt for evidence against their favourite. Treat your own judgement as a useful but unreliable instrument, and build the process to catch its errors. That is not a lack of confidence; it is what confident, experienced hiring actually looks like.","badGood":{"label":"a rejection rationale at debrief","bad":"\"I just didn't click with them — they wouldn't really fit our team, you know? Something felt off.\" — unfalsifiable, names no missing capability, almost certainly affinity bias, and indefensible if the candidate or HR asks why.","good":"\"Against the scorecard they were strong on technical but scored 'weak' on the collaboration and communication capabilities this role was created to fill, with specific evidence from Stage 3. That gap is the reason, not fit.\" — evidence-based, capability-linked, defensible, and honest about what actually decided it."},"miniChallenge":"Your whole panel enthusiastically agrees Candidate A is \"obviously the one\" within the first two minutes of the debrief, before anyone has looked at the scores. You notice the speed and the unanimity and you feel it too. In three or four sentences, decide what you do as the person running the hire.","modelAnswer":"## Example\nFast unanimous consensus before the evidence is on the table is a warning light, not a green one — it usually means the panel is agreeing on a feeling, most likely halo and affinity, rather than on the scores. I would slow it down deliberately: \"Before we lock this in, let's put the independent scores up capability by capability and look at where we disagreed, especially on the communication essential this role was built around.\" Then I would run the disconfirming check out loud — \"what's the strongest evidence A is the wrong hire, and that someone else is right?\" — precisely because I can feel the pull too. If A still wins on the evidence after that, fine; but a decision that cannot survive two minutes of scrutiny was never a decision, it was a reflex.","managersReview":{"intro":"When you review how a manager runs a debrief, look for whether bias is being managed or merely disclaimed:","strengths":["Independent scores recorded before any discussion","Rejections stated as missing capabilities, not \"fit\"","An explicit search for evidence against the favoured candidate","\"Culture add\" scored as a positive, not sameness"],"gaps":["Unanimity reached in minutes, before evidence is examined","The most fluent or most familiar candidate winning by default","No capability-based reason given for rejections"],"improvements":["Add a standing \"disconfirm the favourite\" step to every debrief","Record the evidence behind each score so decisions are defensible to HR and candidates"]}}$ench$::jsonb
from public.modules m join public.courses c on c.id = m.course_id
where l.module_id = m.id and c.slug = 'qa-leadership-academy'
  and m.module_number = 4 and l.lesson_number = 8;

update public.lessons l set enhancements = $ench${"industryStory":"[DAVID INPUT REQUIRED: Add a genuine story of a close senior hiring decision where the \"obviously best\" candidate on paper was not the right hire for the team's actual gap — how you (or a team you advised) reasoned from the gap to a less obvious choice, and how it turned out. This is the emotional centre of the module and a real, non-generic anecdote here would land hard.]","visualAid":{"type":"matrix","title":"Northstar decision matrix — candidates vs weighted capabilities (green = strength, red = gap)","colLabels":["A (10y, tech-strong)","B (4y, reasoning+comms)","C (6y, automation)"],"rowLabels":["Critical thinking / risk","Exploratory breadth (high weight)","Technical / automation (low weight — Dan covers)","Stakeholder communication (high weight — the gap)","Learning potential"],"cells":[[{"label":"Strong","level":"low"},{"label":"Strong","level":"low"},{"label":"Adequate","level":"medium"}],[{"label":"Strong","level":"low"},{"label":"Solid","level":"medium"},{"label":"Weak — a core gap","level":"critical"}],[{"label":"Strong","level":"low"},{"label":"Coachable gap","level":"medium"},{"label":"Strong (redundant)","level":"low"}],[{"label":"Weak — the core gap","level":"critical"},{"label":"Strong","level":"low"},{"label":"Adequate","level":"medium"}],[{"label":"Adequate","level":"medium"},{"label":"High","level":"low"},{"label":"Adequate","level":"medium"}]],"caption":"Read against the gap: A is weak on the highest-weighted capability the role exists to fill; C is strong on the lowest-weighted one; B fits the shape of the gap with a coachable technical gap. Change the gap and the recommendation changes — the method is constant, the answer is contingent."},"davidTip":"The question to put to any panel that is stuck between two strong candidates is not \"who's better?\" — it is \"which of these two weaknesses can this team least afford?\" That single reframe cuts through most deadlocks, because it forces the decision back onto the gap. A team drowning in stakeholder friction cannot afford another brilliant tester who cannot communicate, however good the testing is. A team with no automation cannot afford a superb exploratory reasoner who will not touch the suite. Hire against the weakness you can least survive, not the strength that dazzles you most — and be ready to say \"none of them\" if all the weaknesses are the fatal one.","badGood":{"label":"a final hiring recommendation","bad":"\"We should hire A — he's clearly the strongest candidate, ten years, aced the technical, most experienced by far. B's too junior and C's a bit narrow.\" — ranks testers in the abstract, ignores the defined gap, treats years as suitability, and would give the same answer whatever the team needed.","good":"\"We're recommending B. The role exists to close our exploratory-breadth and stakeholder-communication gap; she's strongest on exactly those, her technical gap is coachable and Dan covers automation. A is the best tester but weak in the one capability we're hiring for; C reinforces a strength we already have. If our gap were automation, I'd recommend C — this is a decision about fit to the gap, and here's the weighted matrix behind it.\" — reasons from the gap, evidence-based, defensible, and honest that the answer is contingent."},"miniChallenge":"Under real pressure to fill the seat before quarter-end, your matrix and evidence point to Candidate B, but Tom (Head of Product) lobbies hard for Candidate A: \"Ten years versus four — we can't turn down that experience, and B's got technical gaps.\" The role was defined around communication and exploratory breadth. In four or five sentences, decide what you recommend and how you handle Tom.","modelAnswer":"## Example\nI would hold the recommendation on B and take Tom's experience point seriously without letting it override the gap. \"Tom, A's ten years are real, but the role exists to close our communication and exploratory-breadth gap — and A's one clear weakness, on our own evidence, is exactly that communication, which for a Payments-facing role is close to disqualifying however strong his testing is. B's gap is technical knowledge, which is coachable and which Dan already covers, so we're trading a fillable gap for a fatal one if we pick A.\" I would show him the weighted matrix so the reasoning is visible rather than a QA-versus-Product opinion clash, and I would name the risk plainly: hiring for years of the wrong shape leaves us with the same stakeholder friction we're trying to fix. If Tom still disagrees, I would escalate the *decision criteria* to Priya rather than argue candidates — because the real question is \"are we hiring for the gap we defined or for a CV?\", and that is a leadership decision I can defend either way it lands.","portfolioBuilder":"Add the **Final Candidate Decision Matrix** to your QA Hiring Pack: the weighted capabilities, the candidate scores from evidence, the computed result, and — most importantly — the one-paragraph rationale defending your choice from the gap. Include a short note showing how the recommendation would change under a different gap. This artefact, more than any other in the pack, demonstrates that you can hire like a leader rather than rank CVs.","resourcePreview":{"name":"Final Candidate Decision Matrix","purpose":"A weighted decision-matrix template for comparing candidates against role-critical capabilities, with space for evidence, weighting and a defensible written rationale.","whenToUse":"At the decision stage, once all interview and practical scores are in, to structure the trade-off and produce a defensible recommendation.","formats":["XLSX","PDF"]}}$ench$::jsonb
from public.modules m join public.courses c on c.id = m.course_id
